package com.scenevibe.accessibilityprobe004;

import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Scalar-only JSON projection. No API accepts an arbitrary string value; package/run headers
 * are generated by the controller. Dynamic text, IDs, titles and errors cannot be serialized.
 */
public final class SafeRow {
    public enum Kind { ARMED, EVENT, CALLBACK_NULL, SNAPSHOT, COALESCED, ACCESS_FAILURE, SESSION_END, TICK_START, TICK_END, TICK_SKIPPED, NODE, CONTROL_MARK }
    public enum Origin { EVENT_TEXT, RECORD, SOURCE_NODE, ACTIVE_ROOT, WINDOW_ROOT, NONE }
    public enum Quality { OK, NULL_SOURCE, NULL_ROOT, REFRESH_FAILED, STALE_EVENT, FUTURE_EVENT,
        UNAVAILABLE, TRUNCATED, ROOT_ONLY, COALESCED_SOURCE, FOREIGN_PACKAGE, CLOCK_INVALID, FRESH_OK, ROOT_UNAVAILABLE, STALE_NODE, INCOMPLETE, TIMEOUT_OR_DELAY }
    public enum Reason { OWNER_STOP, TIME_LIMIT, BYTE_LIMIT, INTERRUPTED, DISCONNECTED, RECONNECTED,
        PROCESS_DESTROYED, IO_FAILURE, CLOCK_INVALID, OVERLOAD }
    public enum Role { TEXT, BUTTON, IMAGE, CONTAINER, GIBBON, UNKNOWN }
    public enum ViewKind { GIBBON_MAIN, PLAYER_CONTAINER, PLAYER, GIBBON, OWN_FIXTURE, OTHER, NONE }
    public enum Trigger { INITIAL, ANDROID_EVENT, PERIODIC_TICK, SYNTHETIC_CONTROL }
    public enum Unit { UNKNOWN }
    public enum RangeState { ABSENT, VALID, INVALID, PASSWORD_SKIPPED }
    public enum Label { NONE, OTHER, AD_LABEL_CANDIDATE, COUNTDOWN_CANDIDATE, PASSWORD_SKIPPED, TOO_LONG }

    public final Kind kind;
    private final Map<String, Object> values = new LinkedHashMap<>();

    /** Create a scalar row of a compiled event category; no advertisement decision exists. */
    public SafeRow(Kind kind) { this.kind = kind; }

    /** Add a numeric scalar under a developer-defined key; never a raw payload. */
    public SafeRow number(String key, long value) { put(key, value); return this; }

    /** Add a finite numeric range value; NaN/Infinity are refused rather than invalid JSON. */
    public SafeRow decimal(String key, double value) {
        if (!Double.isFinite(value)) throw new IllegalArgumentException("Non-finite number");
        put(key, value); return this;
    }

    /** Add a boolean scalar under a developer-defined key. */
    public SafeRow flag(String key, boolean value) { put(key, value); return this; }

    /** Add a compiled enum category, preventing arbitrary string-valued exports. */
    public SafeRow category(String key, Enum<?> value) { put(key, value.name()); return this; }

    /** Reject unsafe keys and duplicate fields so projections have an unambiguous schema. */
    private void put(String key, Object value) {
        if (!key.matches("[a-z][A-Za-z0-9]{0,39}") || values.containsKey(key)
            || key.matches("schemaVersion|runId|sequence|profile|package|provenance|kind|receivedUptimeMs|receivedElapsedRealtimeMs|wallTimeMs")) {
            throw new IllegalArgumentException("Invalid scalar field");
        }
        values.put(key, value);
    }

    /** Serialize internal constants plus typed scalars with provenance and separate clock bases. */
    String json(String run, long seq, ProbeProfile profile, ProbeClock clock) {
        StringBuilder out = new StringBuilder(512);
        out.append("{\"schemaVersion\":2,\"runId\":\"").append(run)
            .append("\",\"sequence\":").append(seq).append(",\"profile\":\"").append(profile.name())
            .append("\",\"package\":\"").append(profile.packageName)
            .append("\",\"provenance\":\"")
            .append(profile == ProbeProfile.OWN_CONTROL ? "OWN_CONTROL" : "TARGET_PLATFORM")
            .append("\",\"kind\":\"").append(kind.name())
            .append("\",\"receivedUptimeMs\":").append(clock.uptime())
            .append(",\"receivedElapsedRealtimeMs\":").append(clock.elapsed())
            .append(",\"wallTimeMs\":").append(clock.wall());
        for (Map.Entry<String, Object> entry : values.entrySet()) {
            out.append(",\"").append(entry.getKey()).append("\":");
            Object value = entry.getValue();
            if (value instanceof String) out.append('"').append(value).append('"');
            else out.append(value);
        }
        return out.append('}').toString();
    }
}
